from pathlib import Path
from html import escape
import json,base64,sys
from render_support import html_text
ROOT=Path(__file__).resolve().parent
def build():
 m=json.loads((ROOT/'compiled_master.json').read_text());e=escape
 out=['''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>AB9MZ Master Field Reference and Section Selector</title>
<style>:root{font-size:22px}*{box-sizing:border-box}body{overflow-wrap:anywhere;background:#fff;color:#000;font-family:Helvetica,Arial,sans-serif;line-height:1.5;margin:0}body.dark{background:#000;color:#fff}header,main,footer{max-width:58rem;margin:auto;padding:clamp(16px,3vw,28px)}h1{font-size:1.6rem;line-height:1.2}h2{font-size:1.4rem;line-height:1.25}h3{font-size:1.2rem}a{color:#003e88}body.dark a{color:#9ddcff}button,input,select{font:inherit}button{max-width:100%;min-width:0;white-space:normal;overflow-wrap:anywhere;padding:.6rem;margin:.3rem .3rem .3rem 0;border:2px solid currentColor;border-radius:.25rem;background:inherit;color:inherit;cursor:pointer}button:disabled{opacity:.6;cursor:default}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible,[tabindex]:focus-visible{outline:4px solid #1467cd;outline-offset:4px}.controls{display:flex;flex-wrap:wrap}.option{display:flex;gap:.6rem;align-items:flex-start;margin:1rem 0;max-width:100%}.option input{width:1.3rem;height:1.3rem;min-width:28px;min-height:28px;flex:none;margin-top:.2rem}.option label{flex:1;min-width:0}.detail{display:block;font-size:.9rem}.download-row{margin-left:clamp(0px,3vw,32px)}fieldset{padding:clamp(12px,3vw,22px);border:2px solid #777;min-width:0}legend{max-width:100%;overflow-wrap:anywhere;font-weight:bold;padding:0 .4rem}section{margin:2rem 0}p,td,th,a,label{overflow-wrap:anywhere}.table-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;margin:1rem 0}td,th{border:1px solid #888;padding:.35rem;text-align:left;vertical-align:top}th{background:#eee;color:#000}body.dark th{background:#222;color:#fff}.spoken{font-size:.85em;display:block}.morse{font-family:Helvetica,Arial,sans-serif;font-weight:bold;font-size:1.2em;white-space:nowrap}summary{cursor:pointer;padding:.5rem}.skip{position:absolute;left:-9999px}.skip:focus{position:static}input[type=file]{max-width:100%}.reading-page{padding:1rem 0;border-bottom:2px solid #777}.meta{font-size:.85rem}#status{min-height:3em}.phonetics-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}@media(max-width:650px){.phonetics-grid{grid-template-columns:1fr}}@media print{header,#selector,#actions,footer,.back{display:none!important}body,body.dark{background:#fff;color:#000}.reading-page{break-before:page;border:0}main{max-width:none;padding:0}.phonetics-grid{grid-template-columns:1fr 1fr}h2{break-after:avoid}}@page{size:letter;margin:1in}</style></head><body>
<a class="skip" href="#selector">Skip to section selection</a><header><h1>Master Field Reference</h1><p>Review draft for Gregg and Patricia. Edition 2.0 for Gregory David Rosenberg, AB9MZ. Select sections to create your own letter-size field book.</p><p>The full phonetic alphabet occupies one print page. Morse letters, numbers, punctuation and procedural signals have their own tables.</p><div class="controls"><button type="button" id="larger">Larger reading text</button><button type="button" id="smaller">Smaller reading text</button><button type="button" id="dark" aria-pressed="false">Dark background</button></div><p role="status" aria-live="polite" aria-atomic="true" id="status">Loading the local document generator.</p><noscript><p>Custom generation needs JavaScript in a full browser. Use the ready-made PDF and Word section files in the complete ZIP if your file preview disables it.</p></noscript></header><main>
<section id="selector" tabindex="-1" aria-labelledby="choose"><h2 id="choose">Choose your sections</h2><p>Tab moves between controls. Space toggles a checkbox. Each section also has its own PDF and Word download.</p><div class="controls"><button type="button" id="select-all">Select all sections</button><button type="button" id="select-none">Clear all sections</button></div><fieldset><legend>Sections to include</legend>''']
 for s in m['sections']:
  sid=s['id'];count=len(s['pages'])
  out.append(f'<div class="option"><input type="checkbox" id="select-{sid}" aria-labelledby="name-{sid}" aria-describedby="count-{sid}" data-section value="{sid}" checked><label for="select-{sid}"><span id="name-{sid}">{e(s["title"])}</span><span id="count-{sid}" class="detail">{count} topic page'+('s' if count!=1 else '')+f'.</span></label></div><p class="download-row"><a href="#read-{sid}" data-read="{sid}" aria-label="Read section: {e(s["title"],quote=True)}">Read section</a></p>')
  out.append(f'<div class="download-row"><button type="button" data-download="{sid}" data-format="pdf" aria-label="Download PDF for {e(s["title"],quote=True)}">Download PDF</button><button type="button" data-download="{sid}" data-format="word" aria-label="Download Word for {e(s["title"],quote=True)}">Download Word</button></div>')
 out.append('''</fieldset><fieldset><legend>Edition options</legend><div class="option"><input type="checkbox" id="include-cover" checked><label for="include-cover">Include cover and contents with new page numbers</label></div><div class="option"><input type="checkbox" id="include-sources" checked><label for="include-sources">Include source pages cited by selected sections</label></div><div class="option"><input type="checkbox" id="front"><label for="front">Start every section on a front-facing page<span class="detail">Adds clearly marked binding spacers where needed.</span></label></div></fieldset></section>
<section id="actions" aria-labelledby="create"><h2 id="create">Create your edition</h2><p id="summary" aria-live="polite" aria-atomic="true"></p><div class="controls"><button type="button" id="pdf">Download selected PDF</button><button type="button" id="word">Download selected Word</button><button type="button" id="read-selection">Read selected sections</button></div><p>The PDF keeps the fixed print layout and binding margins. The Word file is editable and may reflow if fonts or type sizes change. Read the HTML for spoken dit and dah equivalents. Custom PDFs are print editions without tags. For a tagged custom PDF, download Word and export with tagging in your document application. The complete kit also includes tagged review PDFs.</p><details><summary>Save choices and maintain the master</summary><button type="button" id="save-selection">Save my section choices</button><p><label for="load-selection">Load saved section choices</label><br><input id="load-selection" type="file" accept=".json,application/json"></p><button type="button" id="download-source">Download master source</button><p>All editions use this master content. To change shared content, edit master.json in the complete kit and run its rebuild command. Rebuilding creates the master selector and every section again. Editing an exported Word copy does not change the master or other copies.</p></details><p>Open the downloaded HTML in a full browser. A file preview may disable scripts or downloads. If that happens, use the ready-made section files in the ZIP.</p></section><section id="reading" tabindex="-1" aria-labelledby="read-title"><h2 id="read-title">Read selected sections</h2>''')
 for s in m['sections']:
  out.append(f'<section id="read-{s["id"]}" data-preview="{s["id"]}" aria-labelledby="title-{s["id"]}"><h2 id="title-{s["id"]}">{e(s["title"])}</h2>')
  for p in s['pages']:
   out.append(f'<article class="reading-page" aria-labelledby="{p["id"]}"><h3 id="{p["id"]}">{e(p["title"])}</h3>')
   for text in p.get('paragraphs',[]):out.append('<p>'+html_text(text)+'</p>')
   def table(rows,caption):
    z=['<div class="table-scroll" tabindex="0" role="region" aria-label="'+e(caption,quote=True)+'"><table><caption>'+e(caption)+'</caption><thead><tr>']
    z.extend('<th scope="col">'+e(x)+'</th>' for x in rows[0]);z.append('</tr></thead><tbody>')
    for row in rows[1:]:
     z.append('<tr>')
     for ci,cell in enumerate(row):
      tag='th scope="row"' if ci==0 and len(row)>1 else 'td'
      endtag='th' if ci==0 and len(row)>1 else 'td'
      if cell and all(c in '.-' for c in cell):z.append('<'+tag+'><span aria-hidden="true" class="morse">'+e(cell)+'</span><span class="spoken">'+' '.join('dit' if c=='.' else 'dah' for c in cell)+'</span></'+endtag+'>')
      else:z.append('<'+tag+'>'+html_text(cell)+'</'+endtag+'>')
     z.append('</tr>')
    z.append('</tbody></table></div>');return ''.join(z)
   if p.get('table'):
    if s['id'] in ('phonetics','morse') and len(p['table'][0])==4:
     out.append('<div class="phonetics-grid">'+table([['Letter','Morse' if s['id']=='morse' else 'Word']]+[row[:2] for row in p['table'][1:]],p['title']+' A to M')+table([['Letter','Morse' if s['id']=='morse' else 'Word']]+[row[2:] for row in p['table'][1:]],p['title']+' N to Z')+'</div>')
    else:out.append(table(p['table'],p['title']))
   if p.get('note'):out.append('<p>'+html_text(p['note'])+'</p>')
   if p.get('refs'):out.append('<p class="meta">Sources '+', '.join('<a href="#source-'+n.strip()+'" aria-label="Source '+n.strip()+' '+e(next(x['title'] for x in m['sources'] if str(x['id'])==n.strip()),quote=True)+'">'+n.strip()+'</a>' for n in p['refs'].split(','))+'</p>')
   out.append('</article>')
  out.append('<p class="back"><a href="#selector">Back to section selection</a></p></section>')
 out.append('</section><section aria-labelledby="source-title"><h2 id="source-title">Source directory</h2>')
 for s in m['sources']:out.append(f'<p id="source-{s["id"]}"><strong>{s["id"]}. {e(s["title"])}</strong>: {e(s["description"])}<br><a href="{e(s["url"],quote=True)}">Open {e(s["title"])}</a></p>')
 out.append('</section></main><footer><p>Master edition '+m['edition']+' | '+m['date']+' | revision '+m['revision']+'. Generated copies share this revision. The PDF generator creates a print edition; screen-reader navigation is provided in this HTML and the Word headings.</p></footer>')
 out.append('<script id="master-data" type="application/json">'+json.dumps(m,ensure_ascii=False).replace('<','\\u003c')+'</script>')
 out.append('<script id="archive-data" type="application/octet-stream">'+base64.b64encode((ROOT/'content_archive.pdf').read_bytes()).decode()+'</script>')
 for name in ['pdf-lib.min.js','jszip.min.js','book_engine.js','selector.js']:
  code=(ROOT/name).read_text().replace('</script','<\\/script');out.append('<script>'+code+'</script>')
 out.append('</body></html>');(ROOT/'AB9MZ_Master.html').write_text(''.join(out))
 print('Master selector created with',len(m['sections']),'native section checkboxes.')
if __name__=='__main__':build()
